// Test file: src/app/routes/article/article.mapper.test.ts

import { articleMapper } from './article.mapper';

describe('articleMapper - readingTime calculation', () => {

  // Mock article data structure
  const createMockArticle = (bodyContent: string) => ({
    slug: 'test-article',
    title: 'Test Article',
    description: 'Test description',
    body: bodyContent,
    tagList: ['test'],
    createdAt: new Date(),
    updatedAt: new Date(),
    favorited: false,
    favoritesCount: 0,
    author: {
      username: 'testuser',
      bio: null,
      image: null,
      following: false
    }
  });

  describe('Edge Cases - Empty/Null/Undefined Body', () => {

    it('should return readingTime of 1 minute when body is null', () => {
      const article = createMockArticle(null as any);
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(1);
    });

    it('should return readingTime of 1 minute when body is undefined', () => {
      const article = createMockArticle(undefined as any);
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(1);
    });

    it('should return readingTime of 1 minute when body is empty string', () => {
      const article = createMockArticle('');
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(1);
    });

    it('should return readingTime of 1 minute when body contains only whitespace', () => {
      const article = createMockArticle('   \n\t  ');
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(1);
    });
  });

  describe('Short Content - Less than 200 words', () => {

    it('should return readingTime of 1 minute for 50 words', () => {
      const fiftyWords = 'word '.repeat(50).trim();
      const article = createMockArticle(fiftyWords);
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(1);
    });

    it('should return readingTime of 1 minute for 150 words', () => {
      const words150 = 'word '.repeat(150).trim();
      const article = createMockArticle(words150);
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(1);
    });

    it('should return readingTime of 1 minute for exactly 199 words', () => {
      const words199 = 'word '.repeat(199).trim();
      const article = createMockArticle(words199);
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(1);
    });
  });

  describe('Standard Content - 200+ words', () => {

    it('should return readingTime of 1 minute for exactly 200 words', () => {
      const words200 = 'word '.repeat(200).trim();
      const article = createMockArticle(words200);
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(1);
    });

    it('should return readingTime of 2 minutes for 201 words (ceiling test)', () => {
      const words201 = 'word '.repeat(201).trim();
      const article = createMockArticle(words201);
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(2);
    });

    it('should return readingTime of 2 minutes for 400 words', () => {
      const words400 = 'word '.repeat(400).trim();
      const article = createMockArticle(words400);
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(2);
    });

    it('should return readingTime of 3 minutes for 401 words (ceiling test)', () => {
      const words401 = 'word '.repeat(401).trim();
      const article = createMockArticle(words401);
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(3);
    });

    it('should return readingTime of 5 minutes for 1000 words', () => {
      const words1000 = 'word '.repeat(1000).trim();
      const article = createMockArticle(words1000);
      const result = articleMapper(article, null);
      expect(result.readingTime).toBe(5);
    });
  });

  describe('Word Count Extraction - Complex Scenarios', () => {

    it('should correctly count words with multiple spaces between them', () => {
      const multipleSpaces = 'word1    word2     word3';
      const article = createMockArticle(multipleSpaces);
      const result = articleMapper(article, null);
      // 3 words = 1 minute (minimum)
      expect(result.readingTime).toBe(1);
    });

    it('should correctly count words with newlines and tabs', () => {
      const mixedWhitespace = 'word1\nword2\tword3\n\nword4';
      const article = createMockArticle(mixedWhitespace);
      const result = articleMapper(article, null);
      // 4 words = 1 minute (minimum)
      expect(result.readingTime).toBe(1);
    });

    it('should handle leading and trailing whitespace correctly', () => {
      const withWhitespace = '   word1 word2 word3   ';
      const article = createMockArticle(withWhitespace);
      const result = articleMapper(article, null);
      // 3 words = 1 minute (minimum)
      expect(result.readingTime).toBe(1);
    });
  });

  describe('Integration - Verify readingTime field exists in output', () => {

    it('should include readingTime field in mapped article object', () => {
      const article = createMockArticle('test content with some words');
      const result = articleMapper(article, null);
      expect(result).toHaveProperty('readingTime');
      expect(typeof result.readingTime).toBe('number');
    });

    it('should preserve all existing article fields when adding readingTime', () => {
      const article = createMockArticle('test content');
      const result = articleMapper(article, null);
      expect(result).toHaveProperty('slug');
      expect(result).toHaveProperty('title');
      expect(result).toHaveProperty('description');
      expect(result).toHaveProperty('body');
      expect(result).toHaveProperty('tagList');
      expect(result).toHaveProperty('createdAt');
      expect(result).toHaveProperty('updatedAt');
      expect(result).toHaveProperty('favorited');
      expect(result).toHaveProperty('favoritesCount');
      expect(result).toHaveProperty('author');
      expect(result).toHaveProperty('readingTime');
    });
  });
});
